 if(ff.phase==='arriving'){const dist=truck.position.z-truckStop,speed=Math.min(7,1+dist*1.1);truck.position.z=Math.max(truckStop,truck.position.z-speed*dt);wheels.forEach(w=>w.rotation.x-=speed*dt/.4);if(truck.position.z===truckStop){ff.phase='onscene';ff.t=0;planOnScene();}return;}
