function unstick(){const p=player.position;if(canMove(p.x,p.z,obstacles))return;const outside=p.z<-6.6;for(const sameSide of [true,false])for(let r=.2;r<5;r+=.2)for(let a=0;a<24;a++){const x=p.x+Math.cos(a/24*Math.PI*2)*r,z=p.z+Math.sin(a/24*Math.PI*2)*r;if(sameSide&&(outside?z>-7.5:z<-6.6))continue;if(canMove(x,z,obstacles)){p.x=x;p.z=z;return;}}}
